CREATE TABLE catalog (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, name VARCHAR(160) NOT NULL, purpose VARCHAR(48) NOT NULL, tenant VARCHAR(64) DEFAULT 'default' NOT NULL, object_uuid BYTEA NOT NULL, object_slug VARCHAR(190) NOT NULL, object_first_title VARCHAR(255) DEFAULT NULL, object_middle_title TEXT DEFAULT NULL, object_last_title TEXT DEFAULT NULL, object_created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, object_modified_at TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, object_created_by VARCHAR(190) DEFAULT NULL, object_modified_by VARCHAR(190) DEFAULT NULL, object_code VARCHAR(190) DEFAULT NULL, object_active BOOLEAN DEFAULT true NOT NULL, object_enabled BOOLEAN DEFAULT true NOT NULL, object_status VARCHAR(64) DEFAULT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UNIQ_1B2C32474C6A6CB5 ON catalog (object_uuid);
CREATE UNIQUE INDEX UNIQ_1B2C3247588A771 ON catalog (object_slug);
CREATE UNIQUE INDEX uniq_catalog_tenant_code ON catalog (tenant, object_code);
CREATE TABLE category_access_assignment (assignment_id VARCHAR(32) NOT NULL, category_id VARCHAR(26) NOT NULL, actor_user_id VARCHAR(190) NOT NULL, role VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, is_primary BOOLEAN NOT NULL, granted_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, revoked_at TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, PRIMARY KEY (assignment_id));
