CREATE UNIQUE INDEX uniq_category_access_assignment_actor ON category_access_assignment (category_id, actor_user_id);
CREATE TABLE category_attachment (attachment_id VARCHAR(26) NOT NULL, category_id VARCHAR(26) NOT NULL, type VARCHAR(64) NOT NULL, provider VARCHAR(64) NOT NULL, external_attachment_id VARCHAR(255) NOT NULL, path VARCHAR(2048) DEFAULT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (attachment_id));
CREATE INDEX idx_category_attachment_category ON category_attachment (category_id);
CREATE TABLE category_attachment_translation (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, attachment_id VARCHAR(26) NOT NULL, locale VARCHAR(12) NOT NULL, title VARCHAR(180) DEFAULT NULL, alt TEXT DEFAULT NULL, object_uuid BYTEA NOT NULL, object_slug VARCHAR(190) NOT NULL, object_created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, object_modified_at TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, object_created_by VARCHAR(190) DEFAULT NULL, object_modified_by VARCHAR(190) DEFAULT NULL, object_locale VARCHAR(16) NOT NULL, object_timezone VARCHAR(64) NOT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UNIQ_F2ECB1B24C6A6CB5 ON category_attachment_translation (object_uuid);
