CREATE TABLE category_change_request (request_id VARCHAR(64) NOT NULL, category_id VARCHAR(26) NOT NULL, submitted_by VARCHAR(190) NOT NULL, summary VARCHAR(500) NOT NULL, changes JSON NOT NULL, state VARCHAR(32) NOT NULL, reviewed_by VARCHAR(190) DEFAULT NULL, decision_reason TEXT DEFAULT NULL, submitted_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, reviewed_at TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, PRIMARY KEY (request_id));
