CREATE TABLE category (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, name_entity VARCHAR(160) NOT NULL, slug VARCHAR(36) NOT NULL, parent_id INT DEFAULT NULL, path ltree NOT NULL, depth INT NOT NULL, locale VARCHAR(12) DEFAULT NULL, tenant VARCHAR(64) DEFAULT 'default' NOT NULL, workflow_state VARCHAR(32) DEFAULT 'draft' NOT NULL, published BOOLEAN DEFAULT false NOT NULL, published_at TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, icon_url VARCHAR(255) DEFAULT NULL, object_uuid BYTEA NOT NULL, object_slug VARCHAR(190) NOT NULL, object_first_title VARCHAR(255) DEFAULT NULL, object_middle_title TEXT DEFAULT NULL, object_last_title TEXT DEFAULT NULL, object_created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, object_modified_at TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL, object_created_by VARCHAR(190) DEFAULT NULL, object_modified_by VARCHAR(190) DEFAULT NULL, object_active BOOLEAN DEFAULT true NOT NULL, object_enabled BOOLEAN DEFAULT true NOT NULL, object_status VARCHAR(64) DEFAULT NULL, catalog_id INT NOT NULL, PRIMARY KEY (id));
